import random,collections,json,statistics

def simulate(seed,mode,p,nprobe):
 r=random.Random(seed);book=[]
 for page in range(6):
  for row in range(36):
   latent=r.randrange(2);ws=[]
   for j in range(nprobe+8):
    def draw():return latent if r.random()<p else 1-latent
    a,b=draw(),draw()
    if mode=='independent':a=r.randrange(2);b=r.randrange(2)
    if mode=='markov' and j>=nprobe+1:a=ws[-1][1] if r.random()<.85 else 1-ws[-1][1]
    ws.append((a,b))
   book.append((page,latent,ws))
 return book

def evaluate(book,style,nprobe,seed):
 groups=collections.defaultdict(list);errors=0
 for row,(page,latent,words) in enumerate(book):
  vote=sum(w[1] for w in words[:nprobe]);errors+=((vote>=nprobe/2)!=bool(latent));state=latent if style=='oracle' else vote
  for j in range(nprobe,nprobe+8):groups[page,j,state].append((row,j))
 def stat(b):return sum(b[row][2][j][1]==b[row][2][j+1][0] for row in range(len(b)) for j in range(nprobe,nprobe+7))
 movable=sum(len({book[row][2][j] for row,j in cells})>1 for cells in groups.values())
 if movable<30:return {'refused':True,'movable':movable,'proxy_error':errors/len(book)}
 obs=stat(book);r=random.Random(seed);null=[]
 for k in range(39):
  cand=[(page,lat,list(ws)) for page,lat,ws in book]
  for cells in groups.values():
   vals=[book[row][2][j] for row,j in cells];r.shuffle(vals)
   for (row,j),v in zip(cells,vals):cand[row][2][j]=v
   assert collections.Counter(vals)==collections.Counter(cand[row][2][j] for row,j in cells)
  null.append(stat(cand))
 return {'refused':False,'movable':movable,'proxy_error':errors/len(book),'p':(1+sum(v>=obs for v in null))/40}
out={}
for mode,p in [('independent',.8),('latent',.7),('latent',.8),('latent',.9),('markov',.8)]:
 for nprobe in (4,16,32):
  key=f'{mode}_{p}_{nprobe}';one={style:[evaluate(simulate(seed,mode,p,nprobe),style,nprobe,30000+seed) for seed in range(30)] for style in ('oracle','count')}
  out[key]={style:{'runs':vals,'refused':sum(v['refused'] for v in vals),'reject':sum(not v['refused'] and v['p']<=.05 for v in vals),'min_movable':min(v['movable'] for v in vals),'mean_proxy_error':statistics.mean(v['proxy_error'] for v in vals)} for style,vals in one.items()}
print(json.dumps(out,indent=2))

